'use strict';
const fs=require('node:fs'),assert=require('node:assert/strict'),path=require('node:path');
const {webkit,chromium}=require('playwright');
(async()=>{const file=path.resolve('qa/v387/v387-email-preview.html'),html=fs.readFileSync(file,'utf8'),evidence=[];
assert(html.includes('R$ 190,00'));assert(html.includes('Referência do aviso: TR-'));assert(!html.includes('@gmail.com'));
for(const [name,engine]of Object.entries({webkit,chromium})){const browser=await engine.launch({headless:true});for(const width of[320,360,393,430,852,1366]){const page=await browser.newPage({viewport:{width,height:900}});await page.goto('file://'+file);await page.evaluate(()=>document.fonts.ready);const result=await page.evaluate(()=>{const numbers=[...document.querySelectorAll('td')].filter(x=>x.textContent.includes('R$'));return{scroll:document.documentElement.scrollWidth,viewport:innerWidth,numbers:numbers.map(x=>({text:x.textContent,width:x.getBoundingClientRect().width,nowrap:getComputedStyle(x).whiteSpace,height:x.getBoundingClientRect().height})),rows:[...document.querySelectorAll('tbody tr')].length,text:document.body.innerText}});assert(result.scroll<=width+1,`${name} ${width} overflow ${result.scroll}`);assert(result.rows===4);assert(result.text.includes('não repetir a transferência'));for(const n of result.numbers){assert.equal(n.nowrap,'nowrap');assert(n.width>=65)}assert(result.text.includes('Confirme o valor liberado'));await page.screenshot({path:`qa/v387/email-${name}-${width}.png`,fullPage:true});evidence.push({engine:name,width,pass:true,rows:result.rows});await page.close()}await browser.close()}
fs.writeFileSync('qa/v387/email-layout-results.json',JSON.stringify({pass:true,cold_openings:evidence.length,evidence,synthetic:true,actual_inbox_mobile_certified:false},null,2));console.log(JSON.stringify({pass:true,cold_openings:evidence.length}));})().catch(e=>{console.error(e);process.exit(1)});
